t = int(input())
for i in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	(yb, mb, db) = list(map(int, input().split()))
	(yc, mc, dc) = list(map(int, input().split()))
	if yc == yb:
		if mc == mb:
			print(dc - db + 1)
		else:
			ans = a[mb - 1] - db + 1 + sum(a[mb:mc - 1]) + dc
			print(ans)
	else:
		first = a[mb - 1] - db + 1 + sum(a[mb:])
		middle = sum(a) * (yc - yb - 1)
		current = sum(a[:mc - 1]) + dc
		ans = first + middle + current
		ans += (yc - yb) // 4
		for j in range((yc - yb) % 4):
			if (yc - 1 - j) % 4 == 0:
				ans += 1
				break
		print(ans)
